import React, { useEffect, useRef, useState } from 'react';
import { Link, useLocation } from 'react-router-dom';
import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';
import { ScrollToPlugin } from 'gsap/ScrollToPlugin';

// Register GSAP plugins
gsap.registerPlugin(ScrollTrigger);
gsap.registerPlugin(ScrollTrigger, ScrollToPlugin);

const Navbar = () => {
  const [isMenuOpen, setIsMenuOpen] = useState(false);
  const location = useLocation();
  const navRef = useRef();
  const logoRef = useRef();
  const menuItemsRef = useRef([]);
  const hamburgerRef = useRef();
  const mobileMenuRef = useRef();

  useEffect(() => {
    // Initial navbar animation
    gsap.fromTo(navRef.current, 
      { y: -100, opacity: 0 },
      { y: 0, opacity: 1, duration: 1, ease: 'power3.out', delay: 0.2 }
    );

    // Logo animation with enhanced effects
    gsap.fromTo(logoRef.current,
      { scale: 0, rotation: -180 },
      { scale: 1, rotation: 0, duration: 1.2, ease: 'back.out(1.7)', delay: 0.5 }
    );

    // Menu items stagger animation
    gsap.fromTo(menuItemsRef.current,
      { y: -30, opacity: 0 },
      { y: 0, opacity: 1, duration: 0.8, stagger: 0.1, ease: 'power2.out', delay: 0.8 }
    );

    // Navbar scroll effect
    ScrollTrigger.create({
      start: 'top -80',
      end: 99999,
      toggleClass: { targets: navRef.current, className: 'scrolled' }
    });

    return () => {
      ScrollTrigger.getAll().forEach(trigger => trigger.kill());
    };
  }, []);

  const toggleMenu = () => {
    setIsMenuOpen(!isMenuOpen);
    
    if (!isMenuOpen) {
      gsap.fromTo(mobileMenuRef.current, 
        { height: 0, opacity: 0 },
        { 
          height: 'auto', 
          opacity: 1, 
          duration: 0.4, 
          ease: 'power2.out',
          onComplete: () => {
            // Animate menu items
            gsap.fromTo('.mobile-menu-item',
              { x: -30, opacity: 0 },
              { x: 0, opacity: 1, duration: 0.3, stagger: 0.1, ease: 'power2.out' }
            );
          }
        }
      );
    } else {
      gsap.to('.mobile-menu-item',
        { x: -30, opacity: 0, duration: 0.2, stagger: 0.05, ease: 'power2.in' }
      );
      gsap.to(mobileMenuRef.current, {
        height: 0,
        opacity: 0,
        duration: 0.3,
        ease: 'power2.in',
        delay: 0.1
      });
    }
  };

  // Enhanced navigation items with icons
  const navItems = [
    { name: 'Home', path: '/', icon: '🏠' },
    { name: 'About', path: '/about', icon: '👤' },
    { name: 'Works', path: '/works', icon: '💼' },
    { name: 'Services', path: '/services', icon: '⚡' },
    { name: 'Contact', path: '/contact', icon: '📧' }
  ];

  // Check if current path matches navigation item
  const isActiveLink = (path) => {
    if (path === '/' && location.pathname === '/') return true;
    if (path !== '/' && location.pathname.includes(path)) return true;
    return false;
  };

  // Smooth scroll to section for home page
  const handleSectionClick = (sectionName) => {
    if (location.pathname === '/') {
      const element = document.getElementById(sectionName.toLowerCase());
      if (element) {
        gsap.to(window, {
          duration: 1.2,
          scrollTo: { y: element, offsetY: 80 },
          ease: 'power2.inOut'
        });
      }
    }
    setIsMenuOpen(false);
  };

  return (
    <nav 
      ref={navRef}
      className="fixed top-0 left-0 right-0 z-50 bg-ivory/90 backdrop-blur-xl border-b border-rose-quartz/30 transition-all duration-500 shadow-sm"
      style={{ fontFamily: 'Playfair Display, serif' }}
    >
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex justify-between items-center h-16">
          {/* Enhanced Logo */}
          <Link to="/" className="flex items-center space-x-3 cursor-pointer group">
            <div 
              ref={logoRef}
              className="relative"
            >
              <div className="w-12 h-12 bg-gradient-to-br from-electric-indigo via-amaranth-purple to-burnt-umber rounded-full flex items-center justify-center group-hover:scale-110 transition-all duration-300 shadow-lg group-hover:shadow-xl">
                <span className="text-ivory font-bold text-xl group-hover:rotate-12 transition-transform duration-300">C</span>
              </div>
              {/* Animated ring */}
              <div className="absolute inset-0 rounded-full border-2 border-electric-indigo/30 scale-150 opacity-0 group-hover:scale-125 group-hover:opacity-100 transition-all duration-500"></div>
            </div>
            <div className="flex flex-col">
              <span className="text-night font-bold text-xl group-hover:text-electric-indigo transition-colors duration-300">
                Chris
              </span>
              <span className="text-night/60 text-xs font-light -mt-1 group-hover:text-amaranth-purple transition-colors duration-300" style={{ fontFamily: 'Crimson Text, serif' }}>
                Creative Studio
              </span>
            </div>
          </Link>

          {/* Enhanced Desktop Menu */}
          <div className="hidden md:flex items-center space-x-1">
            {navItems.map((item, index) => (
              <div key={item.name} className="relative">
                <Link
                  ref={el => menuItemsRef.current[index] = el}
                  to={item.path}
                  onClick={() => handleSectionClick(item.name)}
                  className={`relative px-4 py-2 rounded-full font-medium transition-all duration-300 group flex items-center space-x-2 ${
                    isActiveLink(item.path)
                      ? 'text-electric-indigo bg-electric-indigo/10'
                      : 'text-night/70 hover:text-electric-indigo hover:bg-rose-quartz/20'
                  }`}
                >
                  <span className="text-sm opacity-60 group-hover:opacity-100 transition-opacity duration-300">
                    {item.icon}
                  </span>
                  <span>{item.name}</span>
                  
                  {/* Enhanced hover effect */}
                  <span className={`absolute bottom-0 left-1/2 transform -translate-x-1/2 w-0 h-0.5 bg-gradient-to-r from-electric-indigo to-amaranth-purple group-hover:w-full transition-all duration-300 ${
                    isActiveLink(item.path) ? 'w-full' : ''
                  }`}></span>
                </Link>
              </div>
            ))}
          </div>

          {/* Enhanced Mobile Menu Button */}
          <button
            ref={hamburgerRef}
            onClick={toggleMenu}
            className="md:hidden relative w-10 h-10 rounded-full flex flex-col justify-center items-center group bg-rose-quartz/20 hover:bg-electric-indigo/20 transition-colors duration-300"
            aria-label="Toggle mobile menu"
          >
            <span className={`block w-5 h-0.5 bg-night transition-all duration-300 ${
              isMenuOpen ? 'rotate-45 translate-y-0.5' : '-translate-y-1'
            }`}></span>
            <span className={`block w-5 h-0.5 bg-night transition-all duration-300 ${
              isMenuOpen ? 'opacity-0' : 'opacity-100'
            }`}></span>
            <span className={`block w-5 h-0.5 bg-night transition-all duration-300 ${
              isMenuOpen ? '-rotate-45 -translate-y-0.5' : 'translate-y-1'
            }`}></span>
          </button>
        </div>

        {/* Enhanced Mobile Menu */}
        <div 
          ref={mobileMenuRef}
          className="md:hidden overflow-hidden bg-ivory/95 backdrop-blur-lg rounded-b-2xl border-t border-rose-quartz/20"
          style={{ height: 0, opacity: 0 }}
        >
          <div className="py-6 px-4 space-y-2">
            {navItems.map((item, index) => (
              <Link
                key={item.name}
                to={item.path}
                onClick={() => handleSectionClick(item.name)}
                className={`mobile-menu-item flex items-center space-x-3 px-4 py-3 rounded-xl font-medium transition-all duration-300 ${
                  isActiveLink(item.path)
                    ? 'text-electric-indigo bg-electric-indigo/10 shadow-sm'
                    : 'text-night/70 hover:text-electric-indigo hover:bg-rose-quartz/30'
                }`}
                style={{ fontFamily: 'Crimson Text, serif' }}
              >
                <span className="text-lg">{item.icon}</span>
                <span className="text-lg">{item.name}</span>
                {isActiveLink(item.path) && (
                  <div className="ml-auto w-2 h-2 bg-electric-indigo rounded-full animate-pulse"></div>
                )}
              </Link>
            ))}
            
            {/* Mobile CTA */}
            <div className="pt-4 mt-4 border-t border-rose-quartz/30">
              <Link
                to="/contact"
                className="mobile-menu-item w-full flex items-center justify-center space-x-2 px-4 py-3 bg-gradient-to-r from-electric-indigo to-amaranth-purple text-ivory rounded-xl font-semibold hover:shadow-lg transition-all duration-300"
              >
                <span>✨</span>
                <span>Let's Work Together</span>
              </Link>
            </div>
          </div>
        </div>
      </div>
    </nav>
  );
};

export default Navbar;